import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.util.*;import java.util.List;import java.util.concurrent.*;
public class EventRegistrationApp extends JFrame {
 JTextField name=new JTextField(10),reg=new JTextField(10);JComboBox<String>event=new JComboBox<>(new String[]{"Tech Fest","Cultural Day","Sports Meet"}),filter=new JComboBox<>(new String[]{"All","Tech Fest","Cultural Day","Sports Meet"});
 DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Student","Register No","Event"},0){public boolean isCellEditable(int r,int c){return false;}};JTable table=new JTable(model);JLabel status=new JLabel("Ready");int page=0;final int SIZE=25;RegistrationService service=new RegistrationService();
 public EventRegistrationApp(){setTitle("Campus Event Registration");setLayout(new BorderLayout(6,6));JMenuBar mb=new JMenuBar();JMenu m=new JMenu("File");JMenuItem refresh=new JMenuItem("Refresh"),exit=new JMenuItem("Exit");m.add(refresh);m.add(exit);mb.add(m);setJMenuBar(mb);
 JPanel form=new JPanel(new FlowLayout(FlowLayout.LEFT));form.add(new JLabel("Student"));form.add(name);form.add(new JLabel("Register No"));form.add(reg);form.add(event);JButton add=new JButton("Register");form.add(add);
 JPanel filt=new JPanel();filt.add(new JLabel("Filter"));filt.add(filter);JButton apply=new JButton("Apply"),prev=new JButton("Previous"),next=new JButton("Next"),csv=new JButton("Export CSV");filt.add(apply);filt.add(prev);filt.add(next);filt.add(csv);
 JPanel north=new JPanel(new BorderLayout());north.add(form,BorderLayout.NORTH);north.add(filt,BorderLayout.SOUTH);add(north,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);add(status,BorderLayout.SOUTH);
 add.addActionListener(e->register());apply.addActionListener(e->{page=0;load();});filter.addActionListener(e->{page=0;load();});prev.addActionListener(e->{page=Math.max(0,page-1);load();});next.addActionListener(e->{page++;load();});refresh.addActionListener(e->load());exit.addActionListener(e->dispose());csv.addActionListener(e->export());
 setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(850,520);setLocationRelativeTo(null);load();}
 void register(){String n=name.getText(),r=reg.getText(),ev=(String)event.getSelectedItem();status.setText("Registering...");
 new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{service.register(n,r,ev);return null;}protected void done(){try{get();status.setText("Registration successful");name.setText("");reg.setText("");page=0;load();}catch(Exception x){Throwable t=x.getCause()==null?x:x.getCause();JOptionPane.showMessageDialog(EventRegistrationApp.this,t.getMessage(),"Registration error",0);status.setText("Registration failed");}}}.execute();}
 void load(){String ev=(String)filter.getSelectedItem();int off=page*SIZE;status.setText("Loading...");
 new SwingWorker<List<Registration>,Void>(){protected List<Registration> doInBackground()throws Exception{return new RegistrationRepository().page(ev,SIZE,off);}protected void done(){try{model.setRowCount(0);for(Registration r:get())model.addRow(new Object[]{r.id,r.name,r.regNo,r.event});status.setText("Page "+(page+1)+" loaded: "+model.getRowCount()+" rows");}catch(Exception x){status.setText("Database error");JOptionPane.showMessageDialog(EventRegistrationApp.this,x.getMessage());}}}.execute();}
 void export(){JFileChooser c=new JFileChooser();if(c.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(java.io.PrintWriter p=new java.io.PrintWriter(c.getSelectedFile())){for(int j=0;j<model.getColumnCount();j++){if(j>0)p.print(",");p.print(model.getColumnName(j));}p.println();for(int i=0;i<model.getRowCount();i++){for(int j=0;j<model.getColumnCount();j++){if(j>0)p.print(",");p.print("\""+model.getValueAt(i,j)+"\"");}p.println();}status.setText("Current page exported");}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}
 public static void main(String[]a){SwingUtilities.invokeLater(()->new EventRegistrationApp().setVisible(true));}
}